'use strict';
const E=Haven,$=id=>document.getElementById(id),KEY='havenbund-v01';
let state,hadSave=false;
try{let raw=localStorage.getItem(KEY);if(raw){state=E.parseSave(raw);hadSave=true;}}catch(e){console.warn('Spielstand konnte nicht geladen werden',e);}
state=state||E.fresh();let tab='build',build=null,selected=null,hover=null,zoom=1,pan={x:0,y:0},pointer=null,toastTimer,frame=0,routeForm=false;
const resNames={forest:'Wald',fish:'Fischgründe',soil:'Ackerland',salt:'Solequelle',clay:'Lehm'};
const city=()=>state.cities[state.selectedCity]||state.cities[0];
const costs=o=>Object.entries(o).map(([k,v])=>`${v} ${E.GOODS[k]}`).join(' · ')||'kostenlos';
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3600);}
function save(manual=false){try{localStorage.setItem(KEY,JSON.stringify(state));if(manual)toast('Spielstand in diesem Browser gespeichert.');}catch{toast('Speichern nicht möglich. Bitte Browser-Speicher prüfen.');}}
function setTab(t){tab=t;selected=null;build=null;routeForm=false;renderPanel();renderPlacement();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));}
function renderStock(){ $('stock').innerHTML=Object.keys(E.GOODS).map(k=>`<div class="good"><small>${E.GOODS[k]}</small><b>${Math.floor(city().stock[k])}</b><span>/120</span></div>`).join('');$('cityTitle').textContent=city().name;$('cityMeta').textContent=`${city().level?'Dorf':'Siedlung'} · ${E.population(city())} Bewohner · ${city().resources.map(r=>resNames[r]).join(' / ')}`;$('pause').textContent=state.paused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',state.paused?'Simulation fortsetzen':'Simulation pausieren');$('speed').textContent=state.speed+'×';}
function renderCities(){ $('cities').innerHTML=[0,1,2].map(id=>{let c=state.cities.find(c=>c.id===id);return `<button data-city="${id}" class="${state.selectedCity===id?'active':''}">${c?'⌂':'＋'} ${['Lindenhavn','Salzwiek','Lehmau'][id]}${c?'':' gründen'}</button>`;}).join('');$('cities').querySelectorAll('button').forEach(b=>b.onclick=()=>{let id=+b.dataset.city;if(!state.cities[id]){let err=E.found(state,id);if(err){toast(err);return;}toast('Ein neuer Ort gehört zu deinem Bund.');}state.selectedCity=id;build=null;selected=null;pan={x:0,y:0};render();save();});}
function renderPlacement(){$('placement').hidden=!build;$('placement').textContent=build?`${E.DEF[build].name} platzieren · Escape / erneut antippen: abbrechen`:'';}
function renderPanel(){const c=city(),p=$('panel');if(selected){let b=c.buildings.find(b=>b.id===selected);if(!b){selected=null;return renderPanel();}let d=E.DEF[b.type];p.innerHTML=`<button id="backPanel">← Zurück</button><div class="sectionLabel">GEBÄUDE</div><h3>${d?.name||'Hafen & Speicher'}</h3><p class="hint">${d?.desc||'Das Herz deiner Siedlung. Alle verbundenen Betriebe nutzen dieses Lager.'}</p><div class="status ${E.status(c,b)!=='Produziert'&&d?.out?'warn':''}">${E.status(c,b)|| (E.linked(c,b)?'Mit dem Hafen verbunden':'Weg zum Hafen fehlt')}</div>${d?.out?`<div class="progress"><i style="width:${(b.progress||0)/d.every*100}%"></i></div><p class="hint">${d.workers} Arbeitskräfte · ${Math.floor(b.progress||0)} / ${d.every} Sekunden</p><button id="toggleBuilding" class="full">${b.off?'Produktion fortsetzen':'Produktion pausieren'}</button>`:''}${b.type==='farm'?`<label for="farmMode">Anbau auf diesem Hof</label><select id="farmMode"><option value="grain" ${b.mode!=='feed'?'selected':''}>Getreide für Mühle und Brauerei</option><option value="feed" ${b.mode==='feed'?'selected':''}>Pferdefutter für die Fuhrwerke</option></select>`:''}${b.type!=='harbor'?'<button id="demolish" class="danger full">Abbauen · volle Baukosten zurück</button>':''}`;$('backPanel').onclick=()=>{selected=null;renderPanel();};if($('toggleBuilding'))$('toggleBuilding').onclick=()=>{b.off=!b.off;renderPanel();};if($('farmMode'))$('farmMode').onchange=e=>{b.mode=e.target.value;b.progress=0;renderPanel();};if($('demolish'))$('demolish').onclick=()=>{for(let k in d.cost)c.stock[k]=Math.min(120,c.stock[k]+d.cost[k]);c.buildings=c.buildings.filter(x=>x.id!==b.id);selected=null;render();};return;}
if(tab==='build'){p.innerHTML=`<span class="eyebrow">EIN ORT WÄCHST</span><h3>Stein für Stein.</h3><p class="hint">Gebäude wählen, freies Feld antippen. Verbinde es mit dem Hafen.</p><div class="buildGrid">${Object.entries(E.DEF).map(([k,d])=>`<button class="buildCard ${build===k?'selected':''}" data-build="${k}" ${d.resource&&!c.resources.includes(d.resource)?'disabled':''} title="${d.desc}"><span class="icon">${d.icon}</span><strong>${d.name}</strong><small>${costs(d.cost)}</small></button>`).join('')}</div><p class="hint">Wege sind kostenlos. Gebäude lassen sich mit voller Erstattung abbauen. Neue Orte kosten in Lindenhavn 16 Holz und 12 Bretter.</p>`;p.querySelectorAll('[data-build]').forEach(b=>b.onclick=()=>{build=build===b.dataset.build?null:b.dataset.build;selected=null;renderPanel();renderPlacement();});}
if(tab==='trade'){renderTrade();}
if(tab==='town'){let workers=c.buildings.reduce((n,b)=>n+(E.DEF[b.type]?.workers||0),0);p.innerHTML=`<span class="eyebrow">DEINE SIEDLUNG IM BLICK</span><h3>${c.name}</h3><div class="stats"><div><strong>${E.population(c)}</strong><small>BEWOHNER</small></div><div><strong>${workers}</strong><small>ARBEITSPLÄTZE</small></div></div><div class="sectionLabel">VORKOMMEN</div>${c.resources.map(r=>`<span class="tag">${resNames[r]}</span>`).join('')}<div class="sectionLabel">VERSORGUNG</div><div class="status ${c.hunger?'warn':''}">${c.hunger?'Nahrung fehlt. Baue die Versorgung aus.':'Die Grundversorgung ist gesichert.'}</div><p class="hint">Alle 20 Spielsekunden werden ${Math.ceil(E.population(c)/4)} Einheiten Brot, Fisch oder Getreide gegessen.</p><div class="sectionLabel">NÄCHSTER MEILENSTEIN</div><h3>${c.level?'Ein Dorf am Meer':'Vom Hafen zum Dorf'}</h3><p class="hint">20 Bewohner · 8 Brot · 12 Bretter · gesicherte Nahrung. Beim Aufstieg werden Brot und Bretter eingesetzt.</p><button id="upgrade" class="primary full" ${c.level?'disabled':''}>${c.level?'Dorf erreicht ✓':'Zum Dorf aufsteigen'}</button><p class="hint">Weitere Stadtstufen folgen nach diesem Prototyp.</p>`;$('upgrade').onclick=()=>{toast(E.upgrade(c)||'Deine Siedlung ist jetzt ein Dorf!');render();save();};}}
function renderTrade(){let p=$('panel');p.innerHTML=`<span class="eyebrow">WAREN VERBINDEN ORTE</span><h3>Deine Handelswege</h3><p class="hint">Salzwiek liegt jenseits der Bucht. Lehmau ist über Land erreichbar. ${state.deliveries} Waren wurden geliefert.</p><button id="newRoute" class="primary full">＋ Feste Route einrichten</button><div id="routeForm"></div><div id="routeList"></div><p class="hint">Schiff: 10 Holz + 8 Bretter. Fuhrwerk: 6 Holz + 4 Bretter + 4 Futter, mit bereitgestelltem Gespann. Je Landfahrt zusätzlich 1 Futter am Abfahrtsort. Keine Pferdezucht in Version 0.1.</p>`;$('newRoute').onclick=()=>{if(state.cities.length<2){toast('Gründe zunächst einen zweiten Ort.');return;}routeForm=!routeForm;drawRouteForm();};drawRouteForm();renderRouteList();}
function drawRouteForm(){if(!routeForm){$('routeForm').innerHTML='';return;}const opts=state.cities.map(c=>`<option value="${c.id}">${c.name}</option>`).join(''),goods=Object.entries(E.GOODS).map(([k,n])=>`<option value="${k}">${n}</option>`).join('');$('routeForm').innerHTML=`<div class="detail"><label for="rKind">Transport</label><select id="rKind"><option value="sea">Schiff · 24 Sekunden je Fahrt</option><option value="land">Fuhrwerk · 18 Sekunden je Fahrt</option></select><label for="rFrom">Von</label><select id="rFrom">${opts}</select><label for="rTo">Nach</label><select id="rTo">${opts}</select><label for="rOut">Hinfracht</label><select id="rOut">${goods}</select><label for="rBack">Rückfracht</label><select id="rBack">${goods}</select><label for="rAmount">Menge je Fahrt</label><input id="rAmount" type="number" min="1" max="12" value="6"><label for="rReserve">Mindestbestand am jeweiligen Ursprung</label><input id="rReserve" type="number" min="0" max="100" value="4"><button id="createRoute" class="primary full">Route starten</button></div>`;$('rTo').value='1';$('rBack').value='salt';$('createRoute').onclick=()=>{let err=E.route(state,+$('rFrom').value,+$('rTo').value,$('rKind').value,$('rOut').value,$('rBack').value,+$('rAmount').value,+$('rReserve').value);if(err){toast(err);return;}routeForm=false;toast('Die Route fährt jetzt automatisch.');renderTrade();save();};}
function renderRouteList(){if(!$('routeList'))return;$('routeList').innerHTML=state.routes.length?state.routes.map((r,i)=>`<div class="routeCard"><b>${r.kind==='sea'?'⚓':'♞'} ${state.cities[r.from].name} ↔ ${state.cities[r.to].name}</b><p>${E.GOODS[r.out]} → · ← ${E.GOODS[r.back]} · bis ${r.amount} Einheiten</p><p>${r.paused?'Pausiert':r.blocked|| (r.travel?`${r.cargo} ${E.GOODS[r.good]} unterwegs · ${r.travel}s`:'Am Umschlagplatz')}</p><div class="progress"><i style="width:${r.travel?(1-r.travel/r.duration)*100:0}%"></i></div><button data-route="${i}">${r.paused?'Fortsetzen':'Pausieren'}</button></div>`).join(''):'<p class="hint">Noch keine Route. Versorge zuerst deine Siedlung und gründe dann einen weiteren Ort.</p>';$('routeList').querySelectorAll('button').forEach(b=>b.onclick=()=>{state.routes[+b.dataset.route].paused=!state.routes[+b.dataset.route].paused;renderRouteList();});}
const lessons=[
['Holz für den Anfang','Wähle den Holzfäller im Baumenü. Baue ihn neben dem Weg, etwa auf dem freien Feld rechts vom Wohnhaus.',s=>s.cities[0].buildings.some(b=>b.type==='wood'&&E.linked(s.cities[0],b))],
['Aus Holz werden Bretter','Baue ein Sägewerk und verbinde es über Wege mit dem Hafen. Tippe Gebäude an, um fehlende Verbindungen zu sehen.',s=>s.cities[0].buildings.some(b=>b.type==='saw'&&E.linked(s.cities[0],b))],
['Fisch für die Familien','Baue eine Fischerhütte direkt am Ufer und verbinde sie mit dem Hafen. Am unteren Inselrand findest du passende Plätze.',s=>s.cities[0].buildings.some(b=>b.type==='fish'&&E.linked(s.cities[0],b))],
['Raum zum Leben','Baue zwei weitere Wohnhäuser an angeschlossene Wege. Jedes Haus bringt vier Bewohner und damit Arbeitskräfte.',s=>E.population(s.cities[0])>=20],
['Vom Feld zum Mehl','Baue einen Bauernhof und eine Mühle. Beide brauchen einen Weg zum Hafen. Der Hof beginnt mit Getreideanbau.',s=>['farm','mill'].every(t=>s.cities[0].buildings.some(b=>b.type===t&&E.linked(s.cities[0],b)))],
['Der Duft von frischem Brot','Baue eine Bäckerei. Sie braucht Mehl und Brennholz. Sorge für mindestens acht Brot im Lager.',s=>s.cities[0].stock.bread>=8],
['Dein erstes Dorf','Öffne „Siedlung“ und steige zum Dorf auf. Du brauchst 20 Bewohner, 8 Brot, 12 Bretter und gesicherte Nahrung.',s=>s.cities[0].level===1],
['Jenseits der Bucht','Gründe Salzwiek über die Ortsleiste unter der Karte. Dort kannst du Salz gewinnen. Seine erste Versorgung kommt mit den Siedlern.',s=>s.cities.length>=2],
['Ein Bund entsteht','Baue in Salzwiek eine verbundene Saline. Richte dann unter „Handel“ eine Schiffsroute ein: Holz hin, Salz zurück. Erst mit einer echten Lieferung ist das Ziel erreicht.',s=>s.deliveries>0]
];
let tutorialKey='';
function tutorial(){let el=$('tutorial');if(state.skip||state.tutorial>=lessons.length){el.classList.add('tutorialDone');return;}el.classList.remove('tutorialDone');let [title,desc,done]=lessons[state.tutorial],ok=done(state);let key=state.tutorial+':'+ok;if(tutorialKey===key&&el.children.length)return;tutorialKey=key;el.innerHTML=`<div class="top"><span>DER HAFENMEISTER · ${state.tutorial+1} / ${lessons.length}</span><button id="dismissTutorial" aria-label="Anleitung ausblenden">×</button></div><button id="nextLesson" class="primary next" ${ok?'':'disabled'}>${state.tutorial===lessons.length-1?'Abschließen ✓':'Weiter →'}</button><h3>${title}</h3><p>${desc}</p>`;$('dismissTutorial').onclick=()=>{state.skip=true;tutorial();toast('Die Anleitung bleibt über ? erreichbar.');};$('nextLesson').onclick=()=>{state.tutorial++;tutorial();if(state.tutorial===lessons.length)toast('Dein Bund wächst. Entdecke jetzt Lehmau, Ziegel und Bier.');save();};}
function render(){renderStock();renderCities();renderPanel();renderPlacement();tutorial();}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));$('pause').onclick=()=>{state.paused=!state.paused;renderStock();};$('speed').onclick=()=>{state.speed=state.speed===1?2:state.speed===2?4:1;renderStock();};$('save').onclick=()=>save(true);$('help').onclick=()=>{state.paused=true;renderStock();$('helpDialog').showModal();};$('closeHelp').onclick=()=>{$('helpDialog').close();state.paused=false;renderStock();};$('restartTutorial').onclick=()=>{state.tutorial=0;state.skip=false;state.selectedCity=0;state.paused=false;$('helpDialog').close();render();};$('reset').onclick=()=>{if(confirm('Aktuellen Spielstand löschen und neu beginnen?')){state=E.fresh();build=null;selected=null;$('helpDialog').close();render();save();$('welcome').showModal();state.paused=true;}};
$('begin').onclick=()=>{$('welcome').close();state.paused=false;render();save();};$('skipStart').onclick=()=>{$('welcome').close();state.skip=true;state.paused=false;render();save();};$('welcome').addEventListener('cancel',e=>e.preventDefault());$('helpDialog').addEventListener('cancel',()=>{state.paused=false;});window.addEventListener('keydown',e=>{if(e.key==='Escape'){build=null;selected=null;renderPanel();renderPlacement();}});
// Hand-drawn isometric world. All assets are local, procedural vector shapes.
const cv=$('map'),ctx=cv.getContext('2d');let W=800,H=550,tw=48,th=24;
function resize(){const r=cv.getBoundingClientRect();W=r.width;H=r.height;let d=Math.min(devicePixelRatio||1,2);cv.width=W*d;cv.height=H*d;ctx.setTransform(d,0,0,d,0,0);}
new ResizeObserver(resize).observe(cv);
function pos(x,y,z=0){return {x:W/2+(x-y)*tw/2+pan.x,y:H*.49+(x+y-13)*th/2+pan.y-z};}
function poly(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=.8;ctx.stroke();}}
function tile(x,y,fill){let p=pos(x,y);poly([[p.x,p.y-th/2],[p.x+tw/2,p.y],[p.x,p.y+th/2],[p.x-tw/2,p.y]],fill);}
function tree(x,y,size=1){let p=pos(x,y),h=28*zoom*size;ctx.fillStyle='#587451';ctx.fillRect(p.x-2*zoom,p.y-h*.3,4*zoom,h*.4);for(let i=0;i<3;i++)poly([[p.x,p.y-h+i*6*zoom],[p.x-10*zoom*size,p.y-h*.35+i*6*zoom],[p.x+10*zoom*size,p.y-h*.35+i*6*zoom]],['#426c51','#4e7c58','#628a60'][i]);}
function building(b){let p=pos(b.x,b.y),s=zoom,w=16*s,h=14*s,c=city();if(b.type==='road'){tile(b.x,b.y,'#c8bd92');let k=E.linked(c,b)?'#ddd3ad':'#baa988';ctx.fillStyle=k;ctx.beginPath();ctx.ellipse(p.x,p.y,tw*.25,th*.23,0,0,Math.PI*2);ctx.fill();return;}
if(b.type==='harbor'){for(let i=0;i<6;i++){ctx.fillStyle=i%2?'#90764e':'#a58a5e';ctx.fillRect(p.x-23*s,p.y+(-5+i*4)*s,46*s,3*s);}p.y-=8*s;w=23*s;h=20*s;}
if(b.type==='farm'){for(let i=0;i<4;i++)poly([[p.x-21*s,p.y-6*s+i*4*s],[p.x,p.y+4*s+i*4*s],[p.x+20*s,p.y-6*s+i*4*s],[p.x,p.y-16*s+i*4*s]],i%2?'#c7a954':'#b3984d');w=11*s;h=9*s;p.y-=4*s;}
if(b.type==='clay'){poly([[p.x,p.y-8*s],[p.x+18*s,p.y],[p.x,p.y+9*s],[p.x-18*s,p.y]],'#af8164','#8b705b');ctx.fillStyle='#d1a381';ctx.beginPath();ctx.ellipse(p.x,p.y,12*s,5*s,0,0,7);ctx.fill();return;}
poly([[p.x-w,p.y-h],[p.x,p.y-h+8*s],[p.x,p.y+8*s],[p.x-w,p.y]],'#e1d1a8','#9f9979');poly([[p.x,p.y-h+8*s],[p.x+w,p.y-h],[p.x+w,p.y],[p.x,p.y+8*s]],'#b6b79a','#8d967d');
const roof=b.type==='wood'?'#637c5a':b.type==='salt'?'#7d8c81':b.type==='harbor'?'#8d5943':'#ad6548';poly([[p.x-w-3*s,p.y-h],[p.x-3*s,p.y-h-13*s],[p.x+w+3*s,p.y-h],[p.x,p.y-h+9*s]],roof,'#7b654a');poly([[p.x-3*s,p.y-h-13*s],[p.x+w+3*s,p.y-h],[p.x+5*s,p.y-h-4*s]],'#c18057');
ctx.fillStyle='#4c6055';ctx.fillRect(p.x+5*s,p.y-5*s,4*s,7*s);ctx.fillStyle='#8f8061';ctx.fillRect(p.x-11*s,p.y-9*s,4*s,4*s);
if(['bakery','kiln','brew'].includes(b.type)){ctx.fillStyle='#8b624d';ctx.fillRect(p.x+5*s,p.y-h-16*s,5*s,13*s);if(E.status(c,b)==='Produziert'){ctx.fillStyle='#f7f3de88';for(let i=0;i<3;i++){ctx.beginPath();ctx.arc(p.x+(9+Math.sin(frame*.015+i)*3)*s,p.y-h-(22+i*8+(frame*.1%8))*s,(3+i)*s,0,7);ctx.fill();}}}
if(b.type==='mill'){let a=frame*.012,yy=p.y-h-6*s;ctx.strokeStyle='#e9dfbc';ctx.lineWidth=4*s;for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(p.x,yy);ctx.lineTo(p.x+Math.cos(a+i*Math.PI/2)*19*s,yy+Math.sin(a+i*Math.PI/2)*19*s);ctx.stroke();}ctx.fillStyle='#6e6249';ctx.beginPath();ctx.arc(p.x,yy,3*s,0,7);ctx.fill();}
if(b.type==='fish'){ctx.strokeStyle='#596c5b';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(p.x+15*s,p.y);ctx.lineTo(p.x+28*s,p.y-16*s);ctx.lineTo(p.x+30*s,p.y+5*s);ctx.stroke();}
if(b.type==='harbor'){ctx.fillStyle='#3d685e';ctx.fillRect(p.x-3*s,p.y-44*s,2*s,20*s);poly([[p.x-1*s,p.y-44*s],[p.x+12*s,p.y-41*s],[p.x-1*s,p.y-36*s]],'#cfa96a');}
if(E.DEF[b.type]?.out&&!['Produziert','Pausiert'].includes(E.status(c,b))){ctx.fillStyle='#b98244';ctx.beginPath();ctx.arc(p.x,p.y-43*s,6*s,0,7);ctx.fill();ctx.fillStyle='white';ctx.font=`bold ${9*s}px sans-serif`;ctx.textAlign='center';ctx.fillText('!',p.x,p.y-40*s);}
}
function ship(x,y,scale=1){let p=pos(x,y),s=zoom*scale;poly([[p.x-20*s,p.y],[p.x+20*s,p.y],[p.x+12*s,p.y+8*s],[p.x-12*s,p.y+8*s]],'#725d49');ctx.strokeStyle='#826747';ctx.lineWidth=2*s;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x,p.y-38*s);ctx.stroke();poly([[p.x+3*s,p.y-35*s],[p.x+3*s,p.y-5*s],[p.x+24*s,p.y-9*s]],'#f1e5bb');poly([[p.x-3*s,p.y-29*s],[p.x-3*s,p.y-8*s],[p.x-16*s,p.y-8*s]],'#d5c698');}
function draw(){frame++;tw=Math.min(W/16,46)*zoom;th=tw*.5;ctx.clearRect(0,0,W,H);ctx.fillStyle='#b8d0d0';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#d6e4df60';ctx.lineWidth=1;for(let j=0;j<18;j++){let y=(j*47+frame*.06)%H;ctx.beginPath();for(let x=0;x<W;x+=10){let yy=y+Math.sin(x*.012+j)*5; x?ctx.lineTo(x,yy):ctx.moveTo(x,yy);}ctx.stroke();}
for(let sum=0;sum<=26;sum++)for(let x=0;x<14;x++){let y=sum-x;if(y<0||y>13||E.terrain(x,y)==='water')continue;let p=pos(x,y);if(E.coast(x,y)){poly([[p.x-tw/2,p.y],[p.x,p.y+th/2],[p.x+tw/2,p.y],[p.x+tw/2,p.y+6*zoom],[p.x,p.y+th/2+6*zoom],[p.x-tw/2,p.y+6*zoom]],'#a5ae85');}tile(x,y,E.coast(x,y)?'#d0c9a3':['#a4b581','#aabb86','#aebe89','#a7b782'][(x*7+y*3)%4]);}
const c=city();for(let sum=0;sum<=26;sum++)for(let x=0;x<14;x++){let y=sum-x;if(y<0||y>13||E.terrain(x,y)==='water')continue;let b=E.at(c,x,y);if(b){if(selected===b.id)tile(x,y,'#e6cc7c');building(b);}else if((x*17+y*13)%7===0&&y<9&&x<11){if(c.resources.includes('forest'))tree(x,y,.8+(x%3)*.12);else{let p=pos(x,y);ctx.fillStyle=c.id===1?'#eee8d5':'#b98c6b';ctx.beginPath();ctx.ellipse(p.x,p.y,9*zoom,5*zoom,0,0,7);ctx.fill();}}}
// Decorative walkers, not simulated cargo: explicitly disclosed in help.
let roads=c.buildings.filter(b=>b.type==='road');roads.slice(0,7).forEach((b,i)=>{let p=pos(b.x+(Math.sin(frame*.025+i)*.2),b.y),s=zoom;ctx.fillStyle=i%2?'#a76f4d':'#496b67';ctx.fillRect(p.x-2*s,p.y-8*s,4*s,6*s);ctx.fillStyle='#dfc296';ctx.beginPath();ctx.arc(p.x,p.y-10*s,2*s,0,7);ctx.fill();});
ship(11.8,11.5+Math.sin(frame*.005)*.22,.9);ship(1,12.8,.55);
if(hover&&build&&E.terrain(hover.x,hover.y)==='land'){tile(hover.x,hover.y,E.at(c,hover.x,hover.y)?'#c7776080':'#eee2a680');let p=pos(hover.x,hover.y);ctx.fillStyle='#37554d';ctx.font=`${20*zoom}px Georgia`;ctx.textAlign='center';ctx.fillText(E.DEF[build].icon,p.x,p.y);}
requestAnimationFrame(draw);}
function hit(e){let r=cv.getBoundingClientRect(),px=e.clientX-r.left-W/2-pan.x,py=e.clientY-r.top-H*.49-pan.y;let a=px/(tw/2),b=py/(th/2)+13;return {x:Math.round((a+b)/2),y:Math.round((b-a)/2)};}
cv.addEventListener('pointerdown',e=>{pointer={x:e.clientX,y:e.clientY,px:pan.x,py:pan.y,moved:false};cv.setPointerCapture(e.pointerId);});cv.addEventListener('pointermove',e=>{hover=hit(e);if(pointer){let dx=e.clientX-pointer.x,dy=e.clientY-pointer.y;if(Math.hypot(dx,dy)>7)pointer.moved=true;if(pointer.moved){pan.x=pointer.px+dx;pan.y=pointer.py+dy;}}});cv.addEventListener('pointerup',e=>{if(pointer&&!pointer.moved){let h=hit(e);if(build){let err=E.place(city(),build,h.x,h.y);if(err)toast(err);else{toast(E.DEF[build].name+' gebaut.');if(build!=='road')build=null;render();save();}}else{let b=E.at(city(),h.x,h.y);selected=b?.id||null;renderPanel();}}pointer=null;});cv.addEventListener('pointercancel',()=>pointer=null);cv.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.65,Math.min(1.8,zoom+(e.deltaY>0?-.08:.08)));},{passive:false});$('zoomIn').onclick=()=>zoom=Math.min(1.8,zoom+.15);$('zoomOut').onclick=()=>zoom=Math.max(.65,zoom-.15);$('center').onclick=()=>{zoom=1;pan={x:0,y:0};};
render();resize();draw();if(!hadSave){state.paused=true;$('welcome').showModal();}else toast('Willkommen zurück. Dein Spielstand wurde geladen.');
setInterval(()=>{if(document.hidden||$('welcome').open||$('helpDialog').open)return;for(let i=0;i<state.speed;i++)E.tick(state);renderStock();tutorial();if(tab==='trade'&&!selected)renderRouteList();if(tab==='town'&&!selected)renderPanel();if(selected&&!routeForm){const active=document.activeElement;if(active?.tagName!=='SELECT')renderPanel();}if(state.time%10===0)save();},1000);
window.addEventListener('pagehide',()=>save());
